const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const santaMonicaCoast = ee.Geometry.Point([-118.4952, 34.0100]).buffer(5000);
  const targetDate = '2015-10-10';

  // 2. Data Acquisition - Sentinel-2 for algae detection
  let collection = ee.ImageCollection('COPERNICUS/S2')
    .filterBounds(santaMonicaCoast)
    .filterDate(targetDate, ee.Date(targetDate).advance(1, 'day'))
    .filter(ee.Filter.lt('CLOUDY_PIXEL_PERCENTAGE', 30));

  const collectionSize = collection.size().getInfo();
  console.log(`Sentinel-2 images on ${targetDate}: ${collectionSize}`);

  if (collectionSize === 0) {
    console.log("No Sentinel-2 data available for target date.");
    console.log("<answer>C1</answer>");
    return;
  }

  // 3. Get best image (least cloudy)
  const image = collection.sort('CLOUDY_PIXEL_PERCENTAGE').first();

  // 4. Calculate NDCI for chlorophyll detection
  const ndci = image.normalizedDifference(['B5', 'B4']).rename('NDCI');

  // 5. Analyze water pixels only (mask land)
  const waterMask = image.select('B3').lt(0.15); // Simple water mask using blue band

  // 6. Count valid water pixels and calculate mean NDCI
  const stats = ndci.updateMask(waterMask).reduceRegion({
    reducer: ee.Reducer.mean().combine({
      reducer2: ee.Reducer.count(),
      sharedInputs: true
    }),
    geometry: santaMonicaCoast,
    scale: 100,
    maxPixels: 1e9
  });

  const meanNdci = stats.get('NDCI_mean').getInfo();
  const pixelCount = stats.get('NDCI_count').getInfo();

  console.log(`Valid water pixels: ${pixelCount}`);
  console.log(`Mean NDCI: ${meanNdci ? meanNdci.toFixed(3) : 'None'}`);

  // 7. Validation & Final Answer
  if (meanNdci === null || pixelCount === 0) {
    console.log("<answer>C2</answer>");
  } else if (isNaN(meanNdci)) {
    console.log("<answer>C3</answer>");
  } else {
    // NDCI > 0.1 typically indicates elevated chlorophyll (potential algae bloom)
    const bloomDetected = meanNdci > 0.1;
    console.log(`Algae bloom threshold (NDCI > 0.1): ${bloomDetected}`);
    console.log(bloomDetected ? "<answer>A</answer>" : "<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
